CREATE TABLE "GroupAnnouncement" ("id" TEXT NOT NULL PRIMARY KEY, "conversationId" TEXT NOT NULL, "authorId" TEXT NOT NULL, "title" TEXT NOT NULL, "content" TEXT NOT NULL, "pinned" BOOLEAN NOT NULL DEFAULT false, "version" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), FOREIGN KEY ("conversationId") REFERENCES "Conversation"("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("authorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "GroupAnnouncement_conversationId_deletedAt_pinned_createdAt_idx" ON "GroupAnnouncement"("conversationId", "deletedAt", "pinned", "createdAt");
CREATE TABLE "GroupAnnouncementRead" ("announcementId" TEXT NOT NULL, "userId" TEXT NOT NULL, "version" INTEGER NOT NULL, "readAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("announcementId", "userId"), FOREIGN KEY ("announcementId") REFERENCES "GroupAnnouncement"("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "GroupMute" ("conversationId" TEXT NOT NULL, "userId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "reason" TEXT NOT NULL, "until" TIMESTAMP(3), "permanent" BOOLEAN NOT NULL DEFAULT false, "updatedAt" TIMESTAMP(3) NOT NULL, PRIMARY KEY ("conversationId", "userId"), FOREIGN KEY ("conversationId", "userId") REFERENCES "ConversationMember"("conversationId", "userId") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
